tool_input.command:
mkdir -p _tools/scratch && cat > _tools/scratch/Scratch.java << 'EOF'
import org.apache.commons.csv.*;
public class Scratch {
    public static void main(String[] args) throws Exception {
        StringBuilder sb = new StringBuilder();
        CSVPrinter p = new CSVPrinter(sb, CSVFormat.DEFAULT);
        p.printRecords("a", "b", "c");
        System.out.println("[" + sb.toString().replace("\r", "\\r").replace("\n", "\\n") + "]");
        System.out.println("count=" + p.getRecordCount());
    }
}
EOF
CP="target/classes:_tools/lib/13-commons-io-2.22.0.jar"
javac -cp "$CP" -d _tools/scratch _tools/scratch/Scratch.java && java -cp "_tools/scratch:$CP" Scratch
